  and SHOPCD = #{shopcd,jdbcType=VARCHAR}
  and URISIIREKBN = #{urisiirekbn,jdbcType=VARCHAR}
  and TEIREIHASSEINO = #{teireihasseino,jdbcType=VARCHAR}

