mapper.select:
SELECT TUSM.APKIHONCD APKIHONCD , TUSM.SHOPCD SHOPCD , SYKM.MOJISETTEIATAI DNPYKBN , TUSM.TEIREIHASSEINO TEIREIHASSEINO , TUSM.TOKUISAKICD TOKUISAKICD , TKSM.JIGYOSHOCD JIGYOSHOCD , TKSM.TOKUISAKINMN1 TOKUISAKINMN1 , TUSM.SHNCD SHNCD , SHMV.GENZSHNNM GENZSHNNM , SHMV.SHINSHNNM SHINSHNNM , SHMV.SHNNMKIRIKAEDD SHNNMKIRIKAEDD , TUSM.KEIJODD KEIJODD , CNDM1.ITEMNM DNPYHASSEIARINASHIFLG , CNDM2.ITEMNM TEIREIKBN , TUSM.SHRYDYDM SHRYDYDM , TUSM.YUKOKBN YUKOKBN , CNDM3.ITEMNM YUKOKBNNM FROM S02M016T TUSM LEFT OUTER JOIN S02V001T SHMV ON ( TUSM.APKIHONCD = SHMV.APKIHONCD AND TUSM.SHOPCD = SHMV.SHOPCD AND TUSM.SHNCD = SHMV.SHNCD ) LEFT OUTER JOIN S02M013T TKSM ON ( TUSM.APKIHONCD = TKSM.APKIHONCD AND TUSM.SHOPCD = TKSM.SHOPCD AND TUSM.TOKUISAKICD = TKSM.TOKUISAKICD ) LEFT OUTER JOIN S02M006T SYKM ON ( SYKM.APKIHONCD = '000' AND SYKM.SHOPCD = '000' AND SYKM.SETTEINO = '092' AND SYKM.RCRDKBN = 'M' AND SYKM.SETTEICD = TUSM.DNPYKBN ) LEFT OUTER JOIN S01M004T CNDM1 ON ( CNDM1.CONDITIONID = 'CN048' AND CNDM1.SETTEIATAI = TUSM.DNPYHASSEIARINASHIFLG ) LEFT OUTER JOIN S01M004T CNDM2 ON ( CNDM2.CONDITIONID = 'CN190' AND CNDM2.SETTEIATAI = TUSM.TEIREIKBN ) LEFT OUTER JOIN S01M004T CNDM3 ON ( CNDM3.CONDITIONID = 'CN001' AND CNDM3.SETTEIATAI = TUSM.YUKOKBN ) WHERE TUSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND TUSM.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND TUSM.URISIIREKBN = #{urisiirekbn,jdbcType=VARCHAR}
AND TUSM.TOKUISAKICD LIKE #{tokuisakicd,jdbcType=VARCHAR}||'%'
AND TUSM.SHNCD = #{shncd,jdbcType=VARCHAR}
AND TUSM.KEIJODD = #{keijodd,jdbcType=VARCHAR}
AND TUSM.TEIREIKBN IN
#{item,jdbcType=VARCHAR}
AND TUSM.DNPYHASSEIARINASHIFLG = #{dnpyhasseiarinashiflg,jdbcType=VARCHAR}
AND TUSM.SHRYDYDM >= #{shrydydmstr,jdbcType=VARCHAR}
AND TUSM.SHRYDYDM <= #{shrydydmend,jdbcType=VARCHAR}
AND TUSM.YUKOKBN = #{yukokbn,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{akshanijigyoshocd,jdbcType=VARCHAR}
AND TKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
ORDER BY APKIHONCD , SHOPCD , TEIREIHASSEINO

SELECT

    SUM(
        CASE
            WHEN TUSM.JIKAIKEIJODYDM = TUSM.SHOKAIKEIJODYDM THEN
                NVL(TUSM.SHOKAIKIN, 0)
            ELSE
                NVL(TUSM.KIN, 0)
        END
    ) AS SUMMARY


    SUM(NVL(TSSM.RTLRKN, 0)) SUMMARY

FROM
    S02M016T TUSM

LEFT OUTER JOIN S02M048T TSSM
 ON TSSM.APKIHONCD = TUSM.APKIHONCD
AND TSSM.SHOPCD = TUSM.SHOPCD
AND TSSM.TOKUISAKICD = TUSM.TOKUISAKICD
AND TO_CHAR(TO_DATE(TSSM.RTLSTRTDD, 'YYYYMMDD'), 'YYYYMM')  <=  TUSM.JIKAIKEIJODYDM
AND TSSM.HIKIAGEDD IS NULL
AND TSSM.YUKOKBN = #{yukokbn,jdbcType=VARCHAR}

WHERE
    TUSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND TUSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND TUSM.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND TUSM.TEIREIKBN = #{teireikbn,jdbcType=VARCHAR}
AND TUSM.URISIIREKBN = #{urisiirekbn,jdbcType=VARCHAR}
AND TUSM.RTLRKNSHUKEIKBN = #{rtlrknshukeikbn,jdbcType=VARCHAR}
AND TUSM.DNPYHASSEIARINASHIFLG = #{dnpyhasseiarinashiflg,jdbcType=VARCHAR}
AND TUSM.YUKOKBN = #{yukokbn,jdbcType=VARCHAR}
AND #{ym,jdbcType=VARCHAR} BETWEEN TUSM.SHOKAIKEIJODYDM AND TUSM.SHRYDYDM
GROUP BY
    TUSM.APKIHONCD
   ,TUSM.SHOPCD
   ,TUSM.TOKUISAKICD
